INSERT INTO `jobseeker` (`id`, `title`, `url`, `location`, `posted`, `scraped`, `company`, `description`, `type`) VALUES
(515864, 'Τεχνικός Εγκαταστάσεων και Υποστήριξης Ιατρικών Μηχανημάτων', 'https://www.jobseeker.gr/job/raymed-%ce%b5%cf%80%ce%b5-athens-118-%cf%84%ce%b5%cf%87%ce%bd%ce%b9%ce%ba%cf%8c%cf%82-%ce%b5%ce%b3%ce%ba%ce%b1%cf%84%ce%b1%cf%83%cf%84%ce%ac%cf%83%ce%b5%cf%89%ce%bd-%ce%ba%ce%b1%ce%b9-%cf%85%cf%80/', 'Αθήνα, Ελλάδα', '2026-03-31 14:25:22', '2026-03-31 20:00:04', 'RAYMED ΕΠΕ', 'Τεχνικός Εγκαταστάσεων και Υποστήριξης Ιατρικών Μηχανημάτων Λίγα λόγια για την εταιρεία Η Raymed, εταιρεία με κορυφαία θέση στην αγορά μετρητικού εξοπλισμού και εξοπλισμού ποιοτικού ελέγχου και ακτινοπροστασίας για τους τομείς της ακτινοθεραπείας, της πυρηνικής ιατρικής & της ακτινολογίας, προσφέρει θεση εργασίας Τεχνικού Εγκαταστάσεων και Υποστήριξης Ιατρικών Μηχανημάτων με έδρα την Αθήνα.   Περιγραφή καθηκόντων Ο υποψήφιος αφού λάβει την κατάλληλη εκπαίδευση, θα ενταχθεί στην ομάδα τεχνικών που διενεργούν εγκαταστάσεις εξοπλισμού και υποστηρίζουν τεχνικά τους πελάτες μας, τόσο στο πεδίο- στους χώρους τους, όσο και απομακρυσμένα.   Απαραίτητα Προσόντα Απόφοιτος ΤΕΙ ή άλλης σχολής θετικής κατεύθυνσης. Προτιμάται πτυχίο στην ηλεκτρονική, τη βιοϊατρική μηχανική ή σε άλλο σχετικό τομέα. Άριστη γνώση Αγγλικών Άριστη γνώση Η/Υ (επιθυμητά δίκτυα & dicom) Κάτοχος διπλώματος οδήγησης Εκπληρωμένες στρατιωτικές υποχρεώσεις Εργατικότητα και συνέπεια Δεξιότητες επίλυσης προβλημάτων, οργάνωσης και διαχείρισης χρόνου Ικανότητα στην επικοινωνία Διαθεσιμότητα για ταξίδια, για εκπαιδεύσεις και υποστήριξη πελατών εκτός έδρας Εμπειρία στην τεχνική υποστήριξη ιατρικών μηχανημάτων, επιθυμητή   Παροχές: Άριστες συνθήκες εργασίας Εκπαίδευση στα προϊόντα της εταιρίας Πλήρης και αορίστου χρόνου απασχόληση Αποδοχές αναλόγως των προσόντων   Email για αποστολή βιογραφικών : info@raymed.gr Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο avlachou@raymed.gr Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515865, 'Υπάλληλος Αποθήκης – Παγκράτι', 'https://www.jobseeker.gr/job/actionline-%ce%bc%ce%bf%ce%bd%ce%bf%cf%80%cf%81%ce%bf%cf%83%cf%89%cf%80%ce%b7-%ce%b5%cf%80%ce%b5-pagkrati-western-greece-greece-118-%cf%85%cf%80%ce%ac%ce%bb%ce%bb%ce%b7%ce%bb%ce%bf%cf%82-%ce%b1/', 'Παγκράτι 250 07, Ελλάδα', '2026-03-31 12:34:55', '2026-03-31 20:00:04', 'ACTIONLINE ΜΟΝΟΠΡΟΣΩΠΗ ΕΠΕ', '🏢 Σχετικά με την Actionline   Η Actionline είναι μια Ελληνική εταιρεία που προσφέρει ολοκληρωμένες λύσεις HR – Recruitment από το 2011.  Ως υποψήφιος, αποκτάς πρόσβαση σε έργα διαφορετικών κλάδων και μεγάλες εταιρείες, ενώ η ομάδα μας αναλαμβάνει ενεργό ρόλο στην υποστήριξη της επαγγελματικής σου διαδρομής. Αναζητάμε για λογαριασμό πελάτη μας, μεγάλη εταιρεία ψηφιοποίησης Υπάλληλο Αποθήκης για την περιοχή του Παγκρατίου.   📌Τοποθεσία: Παγκράτι 📍   Μοντέλο:  On-site 🗓️ Ημέρες:  5νθήμερη, Δευτέρα έως Παρασκευή 🕗 Ωράριο: : 8:00 – 16:30     🎯 Τι θα κάνεις Θα υποστηρίζεις την ομάδα της ψηφιοποίησης στην μετακίνηση κιβωτίων από την αποθήκη προς τους χώρους εργασίας ✅ Τι ζητάμε Αντίστοιχη προϋπηρεσία σε χώρο αποθήκης Ικανότητα άρσης βαρέων αντικειμένων (10kg-15kg) Εξαιρετικές οργανωτικές δεξιότητες   🎁 Τι προσφέρουμε Μηνιαίες μεικτές αποδοχές: 954€ Μηνιαία ticket card: 100€ Μηνιαία κάλυψη Κάρτας Μέσων Μαζικής Μεταφοράς: 27 € Σταθερό πρωινό ωράριο (Δευτέρα – Παρασκευή) Συνεργασία με έμπειρη και οργανωμένη ομάδα   📞 Πώς να κάνεις αίτηση Αν θέλεις να κάνεις το επόμενο βήμα στην καριέρα σου, κάνε την αίτησή σου τώρα! Για περισσότερες πληροφορίες, μπορείς να επικοινωνήσεις μαζί μας στο 4u@actionline.gr  📧 💡 Αν έχεις απορίες, μπορείς να επικοινωνήσεις με το τμήμα Recruiting στο 210 3637822 Για να κάνετε αίτηση για αυτή την αγγελία εργασίας παρακαλώ επισκεφτείτε τη διεύθυνση apply.workable.com. ', 'Πλήρης απασχόληση'),
(515867, 'Μάγειρας Γ’ Vione Hotel – Πάρος', 'https://www.jobseeker.gr/job/swot-hospitality-%cf%80%ce%ac%cf%81%ce%bf%cf%82-118-%ce%bc%ce%ac%ce%b3%ce%b5%ce%b9%cf%81%ce%b1%cf%82-%ce%b3-vione-hotel-%cf%80%ce%ac%cf%81%ce%bf%cf%82/', 'Πάρος, Ελλάδα', '2026-03-31 10:50:24', '2026-03-31 20:00:05', 'SWOT Hospitality', 'SWOT Hospitality αναζητά να προσλάβει Μάγειρα Γ’ για το ξενοδοχείο Vione Hotel στην Πάρο. Ο Μάγειρας Γ’ θα είναι υπεύθυνος για την προετοιμασία και την παρουσίαση νόστιμων πιάτων σύμφωνα με τα πρότυπα του ξενοδοχείου και την κουλτούρα της τοπικής γαστρονομίας. Requirements: Αποδεδειγμένη εμπειρία σε αντίστοιχη θέση σε 5* ξενοδοχεία ή εστιατόρια. Πτυχίο στη μαγειρική ή σχετική εκπαίδευση. Καλή γνώση των γαστρονομικών τάσεων και αρχών. Ικανότητα να δουλεύει σε ομάδα και να συνεργάζεται αποτελεσματικά. Καλή γνώση της ελληνικής και της αγγλικής γλώσσας. Πάθος για την κουζίνα και προθυμία για συνεχή εκπαίδευση και ανάπτυξη. Δεξιότητες στη διαχείριση χρόνου και ικανότητα εργασίας υπό πίεση. Benefits: Ανταγωνιστικό Πακέτο αποδοχών Διαμονή Διατροφή Αποστολή βιογραφικων στο hr@swot.gr Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@swot.gr Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515868, 'Μάγειρας Γ Petra Suites', 'https://www.jobseeker.gr/job/swot-hospitality-%cf%80%ce%ac%cf%81%ce%bf%cf%82-118-%ce%bc%ce%ac%ce%b3%ce%b5%ce%b9%cf%81%ce%b1%cf%82-%ce%b3-petra-suites/', 'Πάρος, Ελλάδα', '2026-03-28 13:59:14', '2026-03-31 20:00:07', 'SWOT Hospitality', 'Η SWOT Hospitality αναζητά να προσλάβει Μάγειρα Γ’ για το ξενοδοχείο OVEA by Kyma New York in Paros. Ο Μάγειρας Γ’ θα είναι υπεύθυνος για την προετοιμασία και την παρουσίαση νόστιμων πιάτων σύμφωνα με τα πρότυπα του ξενοδοχείου και την κουλτούρα της τοπικής γαστρονομίας. Requirements Αποδεδειγμένη εμπειρία σε αντίστοιχη θέση σε 5* ξενοδοχεία ή εστιατόρια. Πτυχίο στη μαγειρική ή σχετική εκπαίδευση. Καλή γνώση των γαστρονομικών τάσεων και αρχών. Ικανότητα να δουλεύει σε ομάδα και να συνεργάζεται αποτελεσματικά. Καλή γνώση της ελληνικής και της αγγλικής γλώσσας. Πάθος για την κουζίνα και προθυμία για συνεχή εκπαίδευση και ανάπτυξη. Δεξιότητες στη διαχείριση χρόνου και ικανότητα εργασίας υπό πίεση. Benefits Ανταγωνιστικό Πακέτο αποδοχών Διαμονή Διατροφή Αποατολή βιογραφικών στο hr@swot.gr Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@swot.gr Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515869, 'HR & Office Operations Assistant', 'https://www.jobseeker.gr/job/actionline-%ce%bc%ce%bf%ce%bd%ce%bf%cf%80%cf%81%ce%bf%cf%83%cf%89%cf%80%ce%b7-%ce%b5%cf%80%ce%b5-pagkrati-western-greece-greece-118-hr-office-operations-assistant/', 'Παγκράτι 250 07, Ελλάδα', '2026-03-30 08:56:23', '2026-03-31 20:00:07', 'ACTIONLINE ΜΟΝΟΠΡΟΣΩΠΗ ΕΠΕ', '🏢 Σχετικά με την Actionline Η Actionline είναι μια Ελληνική εταιρεία που προσφέρει ολοκληρωμένες λύσεις HR – Recruitment από το 2011.  Ως υποψήφιος, αποκτάς πρόσβαση σε έργα διαφορετικών κλάδων και μεγάλες εταιρείες, ενώ η ομάδα μας αναλαμβάνει ενεργό ρόλο στην υποστήριξη της επαγγελματικής σου διαδρομής. Αναζητάμε για πελάτη μας μεγάλη εταιρεία ψηφιοποίησης, HR & Office Operations Assistant   📌Τοποθεσία: Παγκράτι 📍   Μοντέλο:  On-site 🗓️ Ημέρες:  5νθήμερη, Δευτέρα έως Παρασκευή 🕗 Ωράριο: 09:00-17:30     🔎 Αρμοδιότητες Ρόλου Θα αναλάβεις: Την διαχείριση καθημερινών λειτουργιών γραφείου, συντονισμό τηλεφωνικών κλήσεων και οργάνωση αιτημάτων προς τα στελέχη του HR Την υποστήριξη στον πλήρη κύκλο των συμβάσεων εργασίας (παρακολούθηση λήξεων, ανανεώσεις, ψηφιοποίηση και αρχειοθέτηση εγγράφων) Την λειτουργία ως πρώτο σημείο επαφής για το προσωπικό σε θέματα εργασιακών και μισθοδοσίας, σε άμεση συνεργασία με το Λογιστήριο Την παρακολούθηση και διαχείριση αναλώσιμων ειδών γραφείου, και συντονισμό τεχνικών εργασιών για τη συντήρηση του εξοπλισμού και του χώρου Τον συντονισμό εσωτερικών διαδικασιών, όπως παραλαβές και παραδόσεις εγγράφων και υλικών 🎓 Απαραίτητα Προσόντα Πτυχίο Τριτοβάθμιας Εκπαίδευσης (ΑΕΙ/ΤΕΙ) Αντίστοιχη προϋπηρεσία σε θέση γραμματειακής υποστήριξης ή βοηθού λογιστή Εξοικείωση με το πληροφοριακό σύστημα ΕΡΓΑΝΗ και βασική κατανόηση των διαδικασιών μισθοδοσίας (Payroll) Καλή γνώση χειρισμού Η/Υ (MS Office, ιδιαίτερα Excel) Ανεπτυγμένες οργανωτικές και επικοινωνιακές ικανότητες με προσοχή στη λεπτομέρεια 🎁Η εταιρεία σου προσφέρει; Μηνιαίες μικτές αποδοχές 1200-1400€ Μηνιαία ticket card: 100€ Τοποθεσία σε κεντρικό σημείο με εύκολη πρόσβαση και παροχή 27€ οδοιπορικών / μήνα Εργασία σε ένα σύγχρονο και υποστηρικτικό περιβάλλον 📬 Αν πιστεύεις ότι αυτός ο ρόλος σου ταιριάζει, στείλε μας το βιογραφικό σου σήμερα Για περισσότερες πληροφορίες, επικοινώνησε με την Ομάδα μας στο 2103637585. Για να κάνετε αίτηση για αυτή την αγγελία εργασίας παρακαλώ επισκεφτείτε τη διεύθυνση apply.workable.com. ', 'Πλήρης απασχόληση'),
(515871, 'Cook A’ OVEA Hotel in Paros', 'https://www.jobseeker.gr/job/swot-hospitality-%cf%80%ce%ac%cf%81%ce%bf%cf%82-118-cook-a-ovea-hotel-in-paros/', 'Πάρος, Ελλάδα', '2026-03-27 18:49:28', '2026-03-31 20:00:09', 'SWOT Hospitality', 'Η SWOT Hospitality Management Company αναζητά να προσλάβει για το OVEA Hotel στην Πάρο, για τη σεζόν 2025: Cook A’ / Μάγειρας Α’ Καθήκοντα: Διαχείριση της κουζίνας και επίβλεψη της ομάδας μαγειρικής. Προετοιμασία και μαγείρεμα πιάτων υψηλής ποιότητας σύμφωνα με τις συνταγές και τα πρότυπα του ξενοδοχείου. Διασφάλιση ποιότητας των πιάτων και συμμόρφωση με τις προδιαγραφές παρουσίασης. Εκπαίδευση και καθοδήγηση μελών της ομάδας. Συνεργασία με άλλα τμήματα για την ομαλή λειτουργία της υπηρεσίας. Requirements Προηγούμενη εμπειρία σε ανάλογη θέση (Cook A ή Chef de Partie). Πτυχίο ή πιστοποίηση στην μαγειρική. Ικανότητες στη διοίκηση και στο συντονισμό ομάδας. Γνώσεις διαδικασιών υγιεινής και ασφάλειας τροφίμων. Πάθος για τη μαγειρική και τη δημιουργικότητα. Benefits Διαμονή  Διατροφή Ανταγωνιστικό πακέτο αποδοχών Αποστολή βιογραφικών στο hr@swot.gr Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@swot.gr Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515872, 'εργάτης/εργάτρια παραγωγής και συσκευασίας', 'https://www.jobseeker.gr/job/%ce%b1%cf%81%cf%84%ce%bf%ce%b2%ce%b9%ce%bf%ce%bc%ce%b7%cf%87%ce%b1%ce%bd%ce%b9%ce%b1-%ce%b4%ce%b5%cf%81%ce%b2%ce%b9%cf%83%ce%b7-%ce%b1%ce%b2%ce%b5%ce%b5-%cf%80%ce%b1%cf%84%cf%81%ce%b1-118-%ce%b5%cf%81/', 'Πάτρα, Ελλάδα', '2026-03-27 11:50:18', '2026-03-31 20:00:11', 'ΑΡΤΟΒΙΟΜΗΧΑΝΙΑ ΔΕΡΒΙΣΗ ΑΒΕΕ', 'Ζητείται εργάτης/εργάτρια παραγωγής και συσκευασίας για εργασία σε μονάδα παραγωγής στην Πάτρα. Αρμοδιότητες: • Συμμετοχή στη γραμμή παραγωγής • Συσκευασία προϊόντων • Τακτοποίηση και προετοιμασία παραγγελιών • Τήρηση κανόνων καθαριότητας και ασφάλειας Προσόντα: • Υπευθυνότητα και συνέπεια • Διάθεση για εργασία σε ομαδικό περιβάλλον • Προϋπηρεσία σε αντίστοιχη θέση θα εκτιμηθεί (όχι απαραίτητη) Παροχές: • Σταθερή εργασία • Πλήρης απασχόληση (8ωρο, κυλιόμενες βάρδιες) • Ασφάλιση 📞 Αποστολή βιογραφικού ή επικοινωνία στο τηλέφωνο: dervisisbread@hotmail.com, 2610640531 Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο dervisisbread@hotmail.com Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515873, 'Καμαριέρες Kosea Boutique Hotel στην Κω', 'https://www.jobseeker.gr/job/swot-hospitality-%ce%ba%cf%89%cf%82-118-%ce%ba%ce%b1%ce%bc%ce%b1%cf%81%ce%b9%ce%ad%cf%81%ce%b5%cf%82-kosea-boutique-hotel-%cf%83%cf%84%ce%b7%ce%bd-%ce%ba%cf%89/', 'Κως, Ελλάδα', '2026-03-27 12:26:50', '2026-03-31 20:00:11', 'SWOT Hospitality', 'Η SWOT Hospitality αναζητά: Καμαριέρες για το ξενοδοχείο Kosea Boutique Hotel Αρμοδιότητες: Καθαριότητα και τακτοποίηση δωματίων και κοινών χώρων. Διασφάλιση της ποιότητας και της υγιεινής των χώρων. Υποστήριξη στις ανάγκες των πελατών κατά τη διάρκεια της διαμονής τους Requirements Προηγούμενη εμπειρία σε ανάλογη θέση είναι επιθυμητή α. Καλή γνώση της ελληνικής και αγγλικής γλώσσας. Εξειδικευμένες δεξιότητες καθαρισμού και προσοχή στη λεπτομέρεια. Δυνατότητα εργασίας σε ομάδα και επικοινωνίας με άλλα μέλη του προσωπικού. Επαγγελματική συμπεριφορά και δεξιότητες εξυπηρέτησης πελατών. Benefits Διαμονή Διατροφή Ικανοποιητικό πακέτο αποδοχών Αποστολή βιογραφικών στο hr@swot.gr Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@swot.gr Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515874, 'Bartenders OVEA Hotel Paros', 'https://www.jobseeker.gr/job/swot-hospitality-%cf%80%ce%ac%cf%81%ce%bf%cf%82-118-bartenders-ovea-hotel-paros/', 'Πάρος, Ελλάδα', '2026-03-27 10:03:24', '2026-03-31 20:00:13', 'SWOT Hospitality', 'SWOT Hospitality is thrilled to announce an opportunity for enthusiastic and experienced Bartenders to join the team at Petra Suites in the beautiful setting of Paros. Requirements Craft and serve a wide variety of beverages, ensuring quality and presentation meet company standards Deliver exceptional service with a personal touch to all guests Maintain a clean and organized bar area, ensuring all supplies are stocked Respond to guest requests and handle complaints with professionalism and grace Comply with all health and safety regulations At least 2 years of bartending experience in a high-volume establishment Proficiency in Greek and English; knowledge of additional languages is a plus Strong communication skills and a positive, welcoming demeanor Ability to work effectively under pressure in a fast-paced environment Commitment to delivering outstanding customer experiences Benefits Career development opportunities Excellent working environment Employee wellbeing activities Accommodation Meals Please send your CV at hr@swot.gr   Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@swot.gr Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515875, 'Cook A’ Panorama Serenity Suites Patmos', 'https://www.jobseeker.gr/job/swot-hospitality-%cf%80%ce%ac%cf%84%ce%bc%ce%bf%cf%82-118-cook-a-panorama-serenity-suites-patmos/', 'Πάτμος, 855 00, Ελλάδα', '2026-03-27 09:32:27', '2026-03-31 20:00:13', 'SWOT Hospitality', 'Η SWOT Hospitality Management Company αναζητά να προσλάβει για το ξενοδοχείο Panorama Serenity Suites στην Πάτμο, για τη σεζόν 2026: Cook A’ / Μάγειρας Α’ Καθήκοντα: Διαχείριση και επίβλεψη της κουζίνας, καθώς και της ομάδας μαγειρικής. Προετοιμασία και μαγείρεμα πιάτων υψηλής ποιότητας, σύμφωνα με τις συνταγές και τα πρότυπα του ξενοδοχείου. Διασφάλιση ότι τα πιάτα τηρούν τις προδιαγραφές γεύσης και παρουσίασης. Εκπαίδευση και καθοδήγηση των νεότερων μελών της ομάδας. Συνεργασία με τα υπόλοιπα τμήματα του ξενοδοχείου για την ομαλή λειτουργία της υπηρεσίας. Requirements Προηγούμενη εμπειρία σε αντίστοιχη θέση (Cook A ή Chef de Partie). Πτυχίο ή πιστοποίηση στην μαγειρική. Ικανότητες στη διοίκηση και στο συντονισμό ομάδας. Γνώσεις υγιεινής και ασφάλειας τροφίμων. Πάθος για τη μαγειρική και δημιουργικότητα στη γαστρονομία. Benefits Ανταγωνιστικό πακέτο αποδοχών Διαμονή Διατροφή Αποστολή βιογραφικών στο hr@swot.gr Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@swot.gr Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515876, 'Υπάλληλος Ψηφιοποίησης Εγγράφων | Απογευματινή Βάρδια', 'https://www.jobseeker.gr/job/actionline-%ce%bc%ce%bf%ce%bd%ce%bf%cf%80%cf%81%ce%bf%cf%83%cf%89%cf%80%ce%b7-%ce%b5%cf%80%ce%b5-athens-attica-greece-119-%cf%85%cf%80%ce%ac%ce%bb%ce%bb%ce%b7%ce%bb%ce%bf%cf%82-%cf%88%ce%b7%cf%86/', 'Αθήνα, Ελλάδα', '2026-03-26 10:46:18', '2026-03-31 20:00:15', 'ACTIONLINE ΜΟΝΟΠΡΟΣΩΠΗ ΕΠΕ', '🏢 Σχετικά με την Actionline   Η Actionline είναι μια Ελληνική εταιρεία που προσφέρει ολοκληρωμένες λύσεις HR – Recruitment από το 2011.  Ως υποψήφιος, αποκτάς πρόσβαση σε έργα διαφορετικών κλάδων και μεγάλες εταιρείες, ενώ η ομάδα μας αναλαμβάνει ενεργό ρόλο στην υποστήριξη της επαγγελματικής σου διαδρομής. Αναζητάμε για λογαριασμό πελάτη μας, μεγάλη εταιρεία ψηφιοποίησης υποψήφιους που θα στελεχώσουν την θέση του Υπαλλήλου Ψηφιοποίησης Εγγράφων για την περιοχή της Κατεχάκης και του Παγκρατίου.   📌Τοποθεσία: Κατεχάκη / Παγκράτι 📍   Μοντέλο:  On-site 🗓️ Ημέρες:  5νθήμερη, Δευτέρα έως Παρασκευή 🕗 Ωράριο: : 17:00 – 21:00     🎯 Τι θα κάνεις Συμμετοχή στον πλήρη κύκλο ψηφιοποίησης (κατηγοριοποίηση, ταυτοποίηση αρχείου, ψηφιοποίηση, εσωτερικός έλεγχος, κωδικοποίηση). Χρήση εξειδικευμένου λογισμικού για σάρωση και οργάνωση αρχείων Έλεγχος ποιότητας των ψηφιοποιημένων αρχείων Τήρηση διαδικασιών και πρότυπων αρχειοθέτησης Συνεργασία με την υπόλοιπη ομάδα για την ομαλή εξέλιξη του έργου Κάλυψη αναγκών ψηφιοποίησης και τεκμηρίωσης αρχείων/βιβλίων/χειρογράφων με χρήση ειδικού λογισμικού και σαρωτή (book scanner και flatbed scanner). Συμμετοχή σε εκπαιδευτικά τεχνικά σεμινάρια της Εταιρείας. ✅ Τι ζητάμε Εμπειρία σε έργο Ψηφιοποίησης στη χρήση σαρωτών όπως BookScanner, FlabEd, Hybrid Scanner (επιθυμητό) Εξοικείωση με εργαλεία διαχείρισης ψηφιακών αρχείων Επιθυμητό Πτυχίο Αρχειονομίας-Βιβλιοθηκονομίας ή Ιστορικού-Αρχαιολογικού Καλή εξοικείωση Η/Υ 🎁 Τι προσφέρουμε Μηνιαίες μεικτές αποδοχές: 477€ Μηνιαία Ticket Card: 50€ Μηνιαία κάλυψη Κάρτας Μέσων Μαζικής Μεταφοράς: 27 € Σταθερό πρωινό ωράριο (Δευτέρα – Παρασκευή) Εργασία σε κεντρικό σημείο με άμεση πρόσβαση σε μετρό (Κατεχάκη) Συνεργασία με έμπειρη και οργανωμένη ομάδα 📞 Πώς να κάνεις αίτηση Αν θέλεις να κάνεις το επόμενο βήμα στην καριέρα σου, κάνε την αίτησή σου τώρα! Για περισσότερες πληροφορίες, μπορείς να επικοινωνήσεις μαζί μας στο 4u@actionline.gr  📧 💡 Αν έχεις απορίες, μπορείς να επικοινωνήσεις με το τμήμα Recruiting στο 210 3637822       Για να κάνετε αίτηση για αυτή την αγγελία εργασίας παρακαλώ επισκεφτείτε τη διεύθυνση apply.workable.com. ', 'Μερική Απασχόληση'),
(515878, 'Καμαριέρα/ρης Ξενοδοχείο', 'https://www.jobseeker.gr/job/enimeris-pc-%ce%b5%cf%85%cf%81%cf%8d%cf%84%ce%b5%cf%81%ce%b7-%cf%80%ce%b5%cf%81%ce%b9%ce%bf%cf%87%ce%ae-%ce%bd%ce%bf%ce%bc%ce%bf%cf%8d-%ce%ba%ce%b1%ce%b2%ce%ac%ce%bb%ce%b1%cf%82-118-%ce%ba%ce%b1%ce%bc/', 'Καβάλα, Ελλάδα', '2026-03-24 14:40:45', '2026-03-31 20:00:17', 'Enimeris PC', 'H Enimeris.com σε συνεργασία με Ξενοδοχειακή μονάδα με κατάστημα υγειονομικού ενδιαφέροντος και Beach Bars στην ευρύτερη περιοχή του Νομού Καβάλας αναζητά για συνεργασία Καμαριέρα/ρη υπεύθυνη/νο για την καθαριότητα και την άριστη κατάσταση των δωματίων και κοινόχρηστων χώρων. Η ιδανική υποψήφια διαθέτει προσοχή στη λεπτομέρεια, υπευθυνότητα και θετική διάθεση για εργασία σε ομαδικό περιβάλλον. Αρμοδιότητες: Καθαρισμός και τακτοποίηση δωματίων σύμφωνα με τα πρότυπα της επιχείρησης Αλλαγή σεντονιών, πετσετών και λοιπών ειδών υγιεινής Καθαρισμός και συντήρηση κοινόχρηστων χώρων Έλεγχος εξοπλισμού δωματίων και αναφορά φθορών Συνεργασία με την υπόλοιπη ομάδα για την ομαλή λειτουργία της υπηρεσίας καθαριότητας Τήρηση κανόνων υγιεινής και ασφάλειας Εξασφάλιση θετικής εμπειρίας των φιλοξενούμενων μέσω καθαρού και οργανωμένου περιβάλλοντος Συμμόρφωση με τις διαδικασίες λειτουργίας και πρότυπα καθαριότητας Διαχείριση αποθεμάτων καθαριστικών και ειδών υγιεινής Υποστήριξη σε ειδικές ανάγκες ή εκτάκτως αιτήματα πελατών Προσόντα: Άδεια εργασίας και πιστοποιητικό υγείας Προϋπηρεσία σε αντίστοιχη θέση (επιθυμητή αλλά όχι απαραίτητη) Προσοχή στη λεπτομέρεια και υπευθυνότητα Ομαδικό πνεύμα και ευγένεια Ικανότητα εργασίας υπό πίεση Επιθυμητή η γνώση ξένων γλωσσών για επικοινωνία με πελάτες Παροχές: Πλήρης ή μερική απασχόληση Ασφάλιση Συνεχόμενη εκπαίδευση Οι ενδιαφερόμενοι καλούνται να στείλουν το βιογραφικό τους επιλέγοντας αποστολή ή αποστέλλοντας e-mail στο hr@enimeris.com αναγράφοντας στο θέμα ENJSMAI. Όλες οι αιτήσεις και τα βιογραφικά σημειώματα θα αξιολογηθούν με απόλυτη διακριτικότητα. Οι πληροφορίες που παρέχετε θεωρούνται αυστηρά εμπιστευτικές και θα χρησιμοποιηθούν αποκλειστικά για σκοπούς αξιολόγησης της υποψηφιότητάς σας. Επιπλέον, θα υπάρξει επικοινωνία μόνο με τους υποψηφίους που θα επιλεγούν ως επικρατέστεροι για τη συγκεκριμένη θέση. Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@enimeris.com Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515879, 'Sushi Chef', 'https://www.jobseeker.gr/job/enimeris-pc-%ce%b5%cf%85%cf%81%cf%8d%cf%84%ce%b5%cf%81%ce%b7-%cf%80%ce%b5%cf%81%ce%b9%ce%bf%cf%87%ce%ae-%ce%bd%ce%bf%ce%bc%ce%bf%cf%8d-%ce%ba%ce%b1%ce%b2%ce%ac%ce%bb%ce%b1%cf%82-118-sushi-chef/', 'Καβάλα, Ελλάδα', '2026-03-24 14:43:58', '2026-03-31 20:00:17', 'Enimeris PC', 'H Enimeris.com σε συνεργασία με Ξενοδοχειακή μονάδα με κατάστημα υγειονομικού ενδιαφέροντος και Beach Bars στην ευρύτερη περιοχή του Νομού Καβάλας αναζητά Sushi Chef. Ο/Η Sushi Chef, θα έχει την ευθύνη για την παρασκευή και παρουσίαση αυθεντικών ιαπωνικών πιάτων υψηλής ποιότητας, διασφαλίζοντας την φρεσκάδα και την αισθητική κάθε πιάτου. Θα συνεργάζεται στενά με την ομάδα κουζίνας για να διατηρείτε η ομαλή ροή εργασίας, ενώ θα συμβάλλει στη δημιουργία νέων πιάτων και στη συνεχή βελτίωση του μενού. Η θέση απαιτεί αυστηρή τήρηση κανόνων υγιεινής και ασφάλειας τροφίμων, οργανωτικές δεξιότητες και πάθος για την ιαπωνική κουζίνα. Αρμοδιότητες : Παρασκευή και παρουσίαση sushi, sashimi και άλλων ιαπωνικών πιάτων υψηλής ποιότητας. Διασφάλιση της φρεσκάδας και ποιότητας των πρώτων υλών. Προσαρμογή παρασκευής πιάτων ανάλογα με τις προτιμήσεις πελατών ή ειδικές διατροφικές ανάγκες. Τήρηση αυστηρών κανόνων υγιεινής και ασφάλειας τροφίμων (HACCP). Οργάνωση και συντήρηση της κουζίνας sushi, συμπεριλαμβανομένων εξοπλισμού και εργαλείων. Δημιουργία νέων πιάτων και μενού με βάση τις τάσεις και την εποχικότητα των υλικών. Διαχείριση αποθεμάτων και παραγγελιών πρώτων υλών. Εκπαίδευση και καθοδήγηση βοηθών κουζίνας ή junior sushi chefs. Συνεργασία με το υπόλοιπο προσωπικό κουζίνας για ομαλή ροή εργασίας. Τήρηση προτύπων παρουσίασης φαγητού σύμφωνα με το εστιατόριο. Διαχείριση χρόνου και παραγγελιών για αποτελεσματική εξυπηρέτηση πελατών. Συνεχής ενημέρωση για νέες τεχνικές και τάσεις στη sushi κουζίνα. Απαιτούμενα Προσόντα: Προϋπηρεσία ως Sushi Chef ή σε παρόμοια θέση. Άδεια εργασίας και Πιστοποιητικό υγείας για ΚΥΑ Άριστη γνώση τεχνικών παρασκευής sushi, sashimi και άλλων ιαπωνικών πιάτων. Ικανότητα χειρισμού εξοπλισμού κουζίνας sushi με ασφάλεια. Ικανότητες οργάνωσης και διαχείρισης χρόνου. Δημιουργικότητα και αίσθηση παρουσίασης πιάτων. Καλή επικοινωνία και ομαδικό πνεύμα. Γνώση κανόνων υγιεινής και ασφάλειας τροφίμων. Παροχές: Πλήρης απασχόληση Μισθός Αναλόγως προσόντων Ασφάλιση Συνεχόμενη εκπαίδευση Οι ενδιαφερόμενοι καλούνται να στείλουν το βιογραφικό τους επιλέγοντας αποστολή ή αποστέλλοντας e-mail στο hr@enimeris.com αναγράφοντας στο θέμα ENJSSHCH. Όλες οι αιτήσεις και τα βιογραφικά σημειώματα θα αξιολογηθούν με απόλυτη διακριτικότητα. Οι πληροφορίες που παρέχετε θεωρούνται αυστηρά εμπιστευτικές και θα χρησιμοποιηθούν αποκλειστικά για σκοπούς αξιολόγησης της υποψηφιότητάς σας. Επιπλέον, θα υπάρξει επικοινωνία μόνο με τους υποψηφίους που θα επιλεγούν ως επικρατέστεροι για τη συγκεκριμένη θέση. Για να κάνετε αίτηση για τη συγκεκριμένη αγγελία εργασίας στείλτε email στο hr@enimeris.com Μπορείτε να κάνετε αίτηση για τη συγκεκριμένη θέση εργασίας αλλά και για άλλες, χρησιμοποιώντας το online βιογραφικό σας. Κάντε κλικ στο σύνδεσμο παρακάτω για να υποβάλλετε το βιογραφικό σας και να τo στείλετε με email στο συγκεκριμένο εργοδότη. ', 'Πλήρης απασχόληση'),
(515880, 'Shisha Boy – Beach Bar', 'https://www.jobseeker.gr/job/enimeris-pc-%ce%b5%cf%85%cf%81%cf%8d%cf%84%ce%b5%cf%81%ce%b7-%cf%80%ce%b5%cf%81%ce%b9%ce%bf%cf%87%ce%ae-%ce%bd%ce%bf%ce%bc%ce%bf%cf%8d-%ce%ba%ce%b1%ce%b2%ce%ac%ce%bb%ce%b1%cf%82-118-shisha-boy/', 'Καβάλα, Ελλάδα', '2026-03-24 14:36:38', '2026-03-31 20:00:19', 'Enimeris PC', 'H Enimeris.com σε συνεργασία με Ξενοδοχειακή μονάδα με κατάστημα υγειονομικού ενδιαφέροντος και Beach Bars στην ευρύτερη περιοχή του Νομού Καβάλας αναζητά για συνεργασία Shisha Boy υπεύθυνο για την προετοιμασία και εξυπηρέτηση shisha, με στόχο την άριστη εμπειρία των πελατών. Ο ιδανικός υποψήφιος είναι υπεύθυνος, οργανωτικός και με θετική διάθεση για εξυπηρέτηση σε δυναμικό τουριστικό περιβάλλον. Αρμοδιότητες: Εξυπηρέτηση επισκεπτών με φιλική και επαγγελματική προσέγγιση Προετοιμασία και παρουσίαση shisha σύμφωνα με τα πρότυπα της επιχείρησης Παρακολούθηση ασφάλειας και σωστής χρήσης του εξοπλισμού Αντικατάσταση κάρβουνων, γέμιση νερού και καθαρισμός σωλήνων Διατήρηση καθαριότητας στον χώρο shisha και στην περιοχή εργασίας Συνεργασία με το bar και την ομάδα service για ομαλή λειτουργία Έλεγχος αποθεμάτων αρωμάτων, κάρβουνων και αναλώσιμων Υποστήριξη επισκεπτών για πληροφορίες σχετικά με shisha επιλογές Τήρηση κανόνων υγιεινής και ασφαλούς χειρισμού εξοπλισμού Διατήρηση θετικής εμπειρίας πελατών Προσόντα: Προϋπηρεσία σε αντίστοιχη θέση (shisha bar ή lounge) Οργανωτικότητα και υπευθυνότητα Καλή γνώση αγγλικών για επικοινωνία με επισκέπτες Ομαδικό πνεύμα και ευγένεια Επιθυμητή εμπειρία σε τουριστικά καταλύματα ή beach bar Παροχές: Πλήρης ή μερική απασχόληση Ασφάλιση Συνεχόμενη εκπαίδευση Οι ενδιαφερόμενοι καλούνται να στείλουν το βιογραφικό τους επιλέγοντας αποστολή ή αποστέλλοντας e-mail στο hr@enimeris.com αναγράφοντας στο θέμα ENJSSHI. Όλες οι αιτήσεις και τα βιογραφικά σημειώματα θα αξιολογηθούν με απόλυτη διακριτικότητα. Οι πληροφορίες που παρέχετε θεωρούνται αυστηρά εμπιστευτικές και θα χρησιμοποιηθούν αποκλειστικά για σκοπούς α